import{_ as e,o as a,c as n,a3 as d}from"./chunks/framework.I6s8z2kk.js";const y=JSON.parse('{"title":"Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/analytics.md","filePath":"dev/domain/analytics.md"}'),o={name:"dev/domain/analytics.md"};function i(r,t,s,c,l,m){return a(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h1><p>The <strong>Analytics</strong> module serves dashboards from <strong>rollups</strong> built by <code>analytics:build</code> (daily at 00:30, <code>onOneServer</code>).</p><h2 id="admin-analytics" tabindex="-1">Admin analytics <a class="header-anchor" href="#admin-analytics" aria-label="Permalink to &quot;Admin analytics&quot;">​</a></h2><p>Requires <code>analytics.view</code>. Sections (<code>AnalyticsSection</code>): overview, revenue, bookings, payments, clients, centers, promotions, subscriptions and engagement.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Section</th></tr></thead><tbody><tr><td><code>admin/analytics/overview</code></td><td>Overview</td></tr><tr><td><code>admin/analytics/revenue</code></td><td>Revenue</td></tr><tr><td><code>admin/analytics/bookings</code></td><td>Bookings</td></tr><tr><td><code>admin/analytics/payments</code></td><td>Payments</td></tr><tr><td><code>admin/analytics/clients</code></td><td>Clients</td></tr><tr><td><code>admin/analytics/centers</code></td><td>Centers</td></tr><tr><td><code>admin/analytics/promotions</code></td><td>Promotions</td></tr><tr><td><code>admin/analytics/subscriptions</code></td><td>Subscriptions</td></tr><tr><td><code>admin/analytics/engagement</code></td><td>Client engagement</td></tr><tr><td><code>admin/analytics/home-content</code></td><td><a href="./homepage">Homepage</a> content events</td></tr><tr><td><code>admin/analytics/export</code></td><td>Export</td></tr></tbody></table><h2 id="center-analytics" tabindex="-1">Center analytics <a class="header-anchor" href="#center-analytics" aria-label="Permalink to &quot;Center analytics&quot;">​</a></h2><p><code>GET centers/{center}/analytics</code> (permission <code>analytics.view</code>) shows the center&#39;s own numbers.</p><ul><li>Revenue counts only <strong>Confirmed</strong> and <strong>Completed</strong> purchases where the center is the merchant, compared with the previous period of the same length.</li><li>Analytics are <strong>center-wide</strong>; they are not narrowed by purchase visibility.</li></ul><h2 id="engagement" tabindex="-1">Engagement <a class="header-anchor" href="#engagement" aria-label="Permalink to &quot;Engagement&quot;">​</a></h2><p>Clients report engagement through <code>POST clients/engagement/events</code>. Events are aggregate-only: no personal data is stored.</p>',10)])])}const p=e(o,[["render",i]]);export{y as __pageData,p as default};
